use super::*;
use crate::recurring::Recurring;

/// A hard cap, so a bad cadence can never spin. 5 years of weekly is comfortably inside it.
const MAX_OCCURRENCES: i64 = 400;

pub(crate) fn occurrences(r: &Recurring, from: &str, to: &str) -> Vec<String> {
    let mut out = Vec::new();
    for n in 1..=MAX_OCCURRENCES {
        let Some(at) = step(&r.last_seen, r.cadence, n) else { break };
        if at.as_str() > to {
            break;
        }
        if at.as_str() >= from {
            out.push(at);
        }
    }
    out
}
